// Курс Этичный хакер — СОБРАН АВТОМАТИЧЕСКИ из courses/hack/ (node scripts/build-course.js). Не править вручную.
(function (root) {
  const UNITS = {"lang":"hack","units":[{"id":"hack-u1","title":"Раздел 1. Кто такой этичный хакер","lessons":[{"id":"hack-l1","title":"Белые и чёрные шляпы","emoji":"🎩","intro":"Хакер — человек, который глубоко понимает, как устроены компьютеры, и находит в них слабые места. <b>Белые шляпы</b> (этичные хакеры) ищут дыры, чтобы их <b>закрыть</b>, и работают только с разрешения. <b>Чёрные шляпы</b> взламывают ради вреда — это преступление. Мы учимся быть белой шляпой.","questions":[{"type":"choice","q":"Кто такой этичный хакер?","options":["Специалист, который ищет уязвимости с разрешения владельца, чтобы их закрыть","Тот, кто взламывает аккаунты друзей ради шутки","Тот, кто продаёт чужие пароли","Любой, кто умеет печатать быстро"],"explain":"Главное отличие — разрешение и цель: защитить, а не навредить."},{"type":"choice","q":"Как называют хакеров-преступников?","options":["Чёрные шляпы","Белые шляпы","Синие экраны","Админы"],"explain":"Black hat — взламывают без разрешения ради выгоды или вреда."},{"type":"choice","q":"Что такое «уязвимость»?","options":["Ошибка в программе или настройке, через которую можно навредить","Медленный интернет","Красивый интерфейс","Вирус в компьютере"],"explain":"Уязвимость — слабое место. Задача этичного хакера — найти её раньше злоумышленника."},{"type":"choice","q":"Как называется проверка защиты компании по договору?","options":["Пентест (тест на проникновение)","Спам","Фишинг","Дедлайн"],"explain":"Pentest — законная атака по договору, чтобы найти слабые места."},{"type":"bug","q":"Что здесь неправильно с точки зрения этичного хакера?","code":"Нашёл дыру на сайте школы →\nзашёл в журнал → поменял оценки","options":["Нельзя использовать уязвимость — нужно сообщить владельцу","Нужно было сначала поменять пароль","Ничего, так делают все","Надо было сделать это ночью"],"explain":"Нашёл уязвимость — сообщи ответственным. Использовать её — преступление."},{"type":"input","q":"Как по-английски «тест на проникновение» (коротко)?","answers":["pentest","пентест"],"explain":"Pentest = penetration test."}]},{"id":"hack-l2","title":"Закон и правила","emoji":"⚖️","intro":"В России за взлом есть уголовная статья: <b>ст. 272 УК РФ</b> — неправомерный доступ к компьютерной информации. Даже «просто посмотреть» чужой аккаунт — нарушение. Золотое правило: <b>тренируйся только на своём</b> или на специальных учебных площадках (CTF, учебные стенды).","questions":[{"type":"choice","q":"Где можно законно тренировать навыки взлома?","options":["На своих компьютерах, в CTF и учебных стендах","На сайте любого магазина","В аккаунте одноклассника","На сервере школы, если никто не видит"],"explain":"Только там, где у тебя есть явное разрешение."},{"type":"choice","q":"Друг дал тебе свой пароль «просто так». Можно ли менять его настройки?","options":["Нет, разрешение на вход — не разрешение всё менять","Да, раз дал пароль","Да, если он не узнает","Только ночью"],"explain":"Делай только то, на что есть явное разрешение."},{"type":"choice","q":"Ты нашёл уязвимость на большом сайте. Что делать?","options":["Сообщить владельцам через их форму или программу bug bounty","Написать об этом в чат класса","Проверить, сколько данных можно скачать","Продать знакомому"],"explain":"Это называется «ответственное раскрытие» (responsible disclosure)."},{"type":"choice","q":"Что такое «скоуп» (scope) в пентесте?","options":["Список того, что разрешено проверять","Название вируса","Пароль администратора","Скорость атаки"],"explain":"Выходить за скоуп нельзя — даже если очень интересно."},{"type":"choice","q":"Статья 272 УК РФ — это про…","options":["Неправомерный доступ к компьютерной информации","Нарушение правил дорожного движения","Списывание на контрольной","Громкую музыку"],"explain":"Взлом без разрешения — уголовное преступление."},{"type":"input","q":"Тренироваться можно только на ___ компьютере (одно слово)","answers":["своём","своем"],"explain":"Свой компьютер, свой сервер, учебные площадки."}]},{"id":"hack-l3","title":"CTF и bug bounty","emoji":"🚩","intro":"<b>CTF</b> (Capture The Flag) — соревнования хакеров: в заданиях спрятан «флаг», строка вида <code>flag{...}</code>. Нашёл — получил очки. <b>Bug bounty</b> — компании платят деньги за найденные уязвимости. Так хакеры законно зарабатывают.","questions":[{"type":"choice","q":"Что ищут в CTF-заданиях?","options":["Флаг — секретную строку","Настоящие пароли людей","Ошибки в учебнике","Самый быстрый компьютер"],"explain":"Флаг — доказательство, что задание решено."},{"type":"choice","q":"Что такое bug bounty?","options":["Программа, где компания платит за найденные уязвимости","Игра про жуков","Вирус","Штраф за ошибку"],"explain":"Bounty — награда. Многие компании платят тысячи долларов."},{"type":"output","q":"Какая строка похожа на флаг CTF?","code":"a) password123\nb) flag{h4ck3r_st4rt}\nc) admin","options":["b","a","c","Никакая"],"explain":"Флаги обычно выглядят как flag{...}."},{"type":"choice","q":"Какие бывают категории в CTF?","options":["Web, Crypto, Forensics, Reverse, PWN","Математика, Литература, Физкультура","Только игры","Только пароли"],"explain":"Web — сайты, Crypto — шифры, Forensics — улики в файлах, Reverse — разбор программ."},{"type":"choice","q":"Зачем хакеру программирование?","options":["Чтобы писать свои инструменты и автоматизировать проверки","Незачем, всё делают кнопкой «взломать»","Только для красоты","Чтобы печатать быстрее"],"explain":"Настоящие хакеры почти всегда умеют программировать — чаще всего на Python."},{"type":"input","q":"Расшифруй: CTF = Capture The ___","answers":["Flag","flag"],"explain":"Захвати флаг!"}]},{"id":"hack-p1","title":"Практика: охота за флагом","emoji":"💻","intro":"Хакеры пишут свои инструменты на Python. Нажимай <b>▶️ Запустить</b>, чтобы посмотреть результат, и <b>Проверить</b> — чтобы Питоша прогнал тесты.","questions":[{"type":"code","q":"Первый флаг","task":"Выведи флаг: <code>flag{hello_hacker}</code>","starter":"# напиши код здесь\n","tests":[{"out":"flag{hello_hacker}"}],"hint":"print(\"...\")","solution":"print(\"flag{hello_hacker}\")","explain":"Первый флаг взят!"},{"type":"code","q":"Это флаг?","task":"Программа получает строку. Выведи <code>флаг</code>, если она начинается с <code>flag{</code> и заканчивается на <code>}</code>, иначе — <code>не флаг</code>.","starter":"s = input()\n","tests":[{"stdin":"flag{abc}","out":"флаг"},{"stdin":"password","out":"не флаг"},{"stdin":"flag{abc","out":"не флаг"}],"hint":"Методы строк <code>startswith</code> и <code>endswith</code>.","solution":"s = input()\nif s.startswith(\"flag{\") and s.endswith(\"}\"):\n    print(\"флаг\")\nelse:\n    print(\"не флаг\")","explain":"Так CTF-боты проверяют формат флага."},{"type":"code","q":"Достань флаг","task":"Программа получает строку вида <code>flag{секрет}</code>. Выведи только то, что внутри фигурных скобок.","starter":"s = input()\n","tests":[{"stdin":"flag{abc}","out":"abc"},{"stdin":"flag{h4ck}","out":"h4ck"}],"hint":"Срез: <code>s[5:-1]</code> — без первых 5 символов и последнего.","solution":"s = input()\nprint(s[5:-1])","explain":"Срезы строк — главный инструмент разбора данных."}]}]},{"id":"hack-u2","title":"Раздел 2. Пароли и как их ломают","lessons":[{"id":"hack-l4","title":"Перебор (брутфорс)","emoji":"🔨","intro":"<b>Брутфорс</b> — перебор всех вариантов пароля подряд. Пароль из 4 цифр — это всего 10<sup>4</sup> = 10 000 вариантов, компьютер переберёт их за миг. Каждый новый символ умножает число вариантов. Поэтому <b>длина пароля</b> важнее всего.","questions":[{"type":"choice","q":"Сколько вариантов у PIN-кода из 4 цифр?","options":["10 000","40","1 000","4 000"],"explain":"10 вариантов на каждую позицию: 10·10·10·10 = 10 000."},{"type":"choice","q":"Что такое брутфорс?","options":["Перебор всех вариантов пароля подряд","Угадывание по фото","Вирус в почте","Взлом через Wi-Fi"],"explain":"Brute force — «грубая сила»."},{"type":"output","q":"Сколько вариантов у пароля из 3 маленьких латинских букв?","code":"print(26 ** 3)","options":["17576","78","2626","676"],"explain":"26·26·26 = 17 576."},{"type":"choice","q":"Какой пароль дольше всего перебирать?","options":["korova-letit-na-lunu-2024","Qw1!","123456","password"],"explain":"Длинная фраза из нескольких слов — очень много вариантов."},{"type":"choice","q":"Как сайты защищаются от перебора?","options":["Ограничивают число попыток и ставят паузы, капчу","Просят пароль короче","Показывают пароль на экране","Никак"],"explain":"После 5 неудачных попыток — блокировка на время."},{"type":"input","q":"Самое важное свойство пароля против перебора — его ___","answers":["длина","длинна"],"explain":"Каждый символ умножает число вариантов."}]},{"id":"hack-l5","title":"Атака по словарю","emoji":"📖","intro":"Люди придумывают похожие пароли: <code>123456</code>, <code>qwerty</code>, имя + год. Хакеры собирают <b>словари</b> самых популярных паролей и проверяют сначала их — это намного быстрее перебора. Пароль из словаря ломается за секунды, даже если он длинный: <code>iloveyou</code>.","questions":[{"type":"choice","q":"Почему пароль «qwerty123» плохой?","options":["Он есть во всех словарях популярных паролей","Он слишком длинный","В нём нет русских букв","Он хороший"],"explain":"Популярные пароли проверяют первыми."},{"type":"choice","q":"Что такое «утечка паролей»?","options":["Когда базу паролей сайта украли и выложили в сеть","Когда забыл пароль","Когда пароль короткий","Когда пароль записан на бумажке"],"explain":"Поэтому нельзя использовать один пароль везде."},{"type":"choice","q":"Почему нельзя использовать один пароль на всех сайтах?","options":["Утечёт с одного сайта — взломают все аккаунты","Сайты обидятся","Так запрещено законом","Это неудобно"],"explain":"Это называется credential stuffing — проверка утёкших паролей на других сайтах."},{"type":"choice","q":"Какой пароль лучше?","options":["Случайный из менеджера паролей","Кличка собаки + год рождения","Своё имя","11111111"],"explain":"Личные данные легко узнать из соцсетей."},{"type":"bug","q":"Что не так с паролем?","code":"Пароль: Yaroslav2014","options":["Имя и год легко узнать из соцсетей","Слишком сложный","Нет ошибки","Нужно больше пробелов"],"explain":"Хакер сначала пробует имена, даты, клички."},{"type":"input","q":"Самый популярный пароль в мире (6 цифр подряд)","answers":["123456"],"explain":"Он годами на первом месте во всех утечках."}]},{"id":"hack-l6","title":"Двухфакторная защита","emoji":"📱","intro":"<b>2FA</b> — второй шаг входа: код из SMS, из приложения или ключ. Даже если пароль украли, без второго фактора войти нельзя. Плюс <b>менеджер паролей</b> — программа, которая придумывает и помнит длинные разные пароли за тебя.","questions":[{"type":"choice","q":"Что даёт двухфакторная аутентификация?","options":["Без второго кода не войти, даже зная пароль","Пароль становится короче","Интернет быстрее","Ничего"],"explain":"Второй фактор — то, что есть только у тебя (телефон)."},{"type":"choice","q":"Тебе пишут: «Скажи код из SMS, мы из поддержки». Что делать?","options":["Ничего не говорить — это мошенники","Сказать код","Сказать половину кода","Попросить их сначала сказать свой"],"explain":"Код из SMS никому нельзя сообщать — его просят только мошенники."},{"type":"choice","q":"Что такое менеджер паролей?","options":["Программа, которая хранит разные сложные пароли","Человек, который знает все пароли","Тетрадка","Вирус"],"explain":"Запоминаешь один главный пароль, остальные — длинные случайные."},{"type":"choice","q":"Какие бывают факторы входа?","options":["Знаю (пароль), имею (телефон), являюсь (отпечаток)","Только пароль","Только лицо","Имя и фамилия"],"explain":"Хорошая защита сочетает разные факторы."},{"type":"choice","q":"Что надёжнее как второй фактор?","options":["Приложение-аутентификатор","Секретный вопрос «кличка кота»","Повтор того же пароля","Email без пароля"],"explain":"SMS можно перехватить, а код в приложении — только на твоём телефоне."},{"type":"input","q":"Сокращение двухфакторной аутентификации (2 символа)","answers":["2FA","2fa"],"explain":"Two-Factor Authentication."}]},{"id":"hack-p2","title":"Практика: проверялка паролей","emoji":"💻","intro":"Пишем свои проверялки паролей на Python.","questions":[{"type":"code","q":"Сколько вариантов?","task":"Программа получает длину пароля из цифр <code>n</code>. Выведи, сколько вариантов нужно перебрать.","starter":"n = int(input())\n","tests":[{"stdin":"4","out":"10000"},{"stdin":"6","out":"1000000"}],"hint":"<code>10 ** n</code>","solution":"n = int(input())\nprint(10 ** n)","explain":"Каждая цифра умножает варианты на 10."},{"type":"code","q":"Надёжность пароля","task":"Программа получает пароль. Выведи <code>надёжный</code>, если в нём хотя бы 12 символов, есть цифра и есть буква. Иначе — <code>слабый</code>.","starter":"p = input()\n","tests":[{"stdin":"korova-letit-77","out":"надёжный"},{"stdin":"qwerty","out":"слабый"},{"stdin":"aaaaaaaaaaaaaaa","out":"слабый"},{"stdin":"1234567890123","out":"слабый"}],"hint":"<code>any(c.isdigit() for c in p)</code> — есть ли цифра; <code>c.isalpha()</code> — буква.","solution":"p = input()\nhas_d = any(c.isdigit() for c in p)\nhas_a = any(c.isalpha() for c in p)\nif len(p) >= 12 and has_d and has_a:\n    print(\"надёжный\")\nelse:\n    print(\"слабый\")","explain":"Похоже работают проверки на сайтах при регистрации."},{"type":"code","q":"Пароль из словаря?","task":"В программе есть список популярных паролей. Программа получает пароль и выводит <code>в словаре</code> или <code>нет в словаре</code>.","starter":"top = [\"123456\", \"qwerty\", \"password\", \"111111\", \"iloveyou\"]\np = input()\n","tests":[{"stdin":"qwerty","out":"в словаре"},{"stdin":"Zx9-moloko-dom","out":"нет в словаре"}],"hint":"Оператор <code>in</code>.","solution":"top = [\"123456\", \"qwerty\", \"password\", \"111111\", \"iloveyou\"]\np = input()\nif p in top:\n    print(\"в словаре\")\nelse:\n    print(\"нет в словаре\")","explain":"Хорошие сайты не дают поставить пароль из такого списка."}]}]},{"id":"hack-u3","title":"Раздел 3. Хеши: как сайты хранят пароли","lessons":[{"id":"hack-l7","title":"Что такое хеш","emoji":"🧬","intro":"<b>Хеш</b> — «отпечаток» данных: функция превращает любой текст в строку фиксированной длины. Одинаковый текст → одинаковый хеш, но обратно из хеша текст не получить. Изменишь одну букву — хеш станет совсем другим. Популярные: <code>MD5</code> (старый, ненадёжный), <code>SHA-256</code>.","questions":[{"type":"choice","q":"Можно ли из хеша получить исходный текст обратной функцией?","options":["Нет, хеш работает только в одну сторону","Да, легко","Только по выходным","Только для коротких слов"],"explain":"Хеш-функции односторонние. Подобрать можно только перебором."},{"type":"choice","q":"Что будет с хешем, если поменять одну букву?","options":["Он изменится полностью","Поменяется одна буква хеша","Не изменится","Станет длиннее"],"explain":"Это называется лавинный эффект."},{"type":"choice","q":"Какая длина у хеша SHA-256 в шестнадцатеричном виде?","options":["64 символа","Зависит от текста","8 символов","256 символов"],"explain":"256 бит = 32 байта = 64 hex-символа — для любого текста."},{"type":"choice","q":"Зачем скачанным файлам публикуют хеш?","options":["Чтобы проверить, что файл не подменили","Для красоты","Чтобы файл скачался быстрее","Это пароль от файла"],"explain":"Совпал хеш — файл тот самый."},{"type":"choice","q":"Какой алгоритм устарел и считается небезопасным?","options":["MD5","SHA-256","SHA-3","bcrypt"],"explain":"Для MD5 умеют находить коллизии — разные тексты с одним хешем."},{"type":"input","q":"Модуль Python для хешей называется ___lib","answers":["hash","hashlib"],"explain":"import hashlib"}]},{"id":"hack-l8","title":"Хеши паролей и соль","emoji":"🧂","intro":"Хорошие сайты хранят не пароль, а его хеш. При входе хешируют то, что ты ввёл, и сравнивают. Но одинаковые пароли дают одинаковые хеши — хакеры заранее считают хеши популярных паролей (<b>радужные таблицы</b>). Защита — <b>соль</b>: случайная добавка к паролю перед хешированием, своя у каждого.","questions":[{"type":"choice","q":"Что сайт должен хранить в базе?","options":["Хеш пароля с солью","Пароль как есть","Пароль задом наперёд","Ничего"],"explain":"Тогда при утечке пароли не видны сразу."},{"type":"choice","q":"Зачем нужна соль?","options":["Чтобы одинаковые пароли давали разные хеши","Чтобы хеш стал короче","Для вкуса","Чтобы пароль стал проще"],"explain":"Соль ломает заранее посчитанные таблицы хешей."},{"type":"choice","q":"Что такое радужная таблица?","options":["Заранее посчитанные хеши популярных паролей","Таблица цветов","Расписание уроков","База вирусов"],"explain":"Без соли хеш «123456» находят мгновенно."},{"type":"choice","q":"Сайт прислал тебе твой забытый пароль по почте. Что это значит?","options":["Он хранит пароли открыто — это плохо","Он очень надёжный","Так и надо","Почта взломана"],"explain":"Нормальный сайт не знает твой пароль и может дать только сброс."},{"type":"choice","q":"Какие функции специально сделаны медленными для паролей?","options":["bcrypt, Argon2","MD5","print","len"],"explain":"Медленный хеш — перебор становится в тысячи раз дольше."},{"type":"input","q":"Случайная добавка к паролю перед хешированием — это ___","answers":["соль","salt"],"explain":"Salt."}]},{"id":"hack-p3","title":"Практика: hashlib","emoji":"💻","intro":"Модуль <code>hashlib</code> — настоящие хеш-функции, как на серверах.","questions":[{"type":"code","q":"Хеш SHA-256","task":"Программа получает строку. Выведи её хеш SHA-256 (hex).","starter":"import hashlib\ns = input()\n","tests":[{"stdin":"hello","out":"2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824"}],"hint":"<code>hashlib.sha256(s.encode()).hexdigest()</code>","solution":"import hashlib\ns = input()\nprint(hashlib.sha256(s.encode()).hexdigest())","explain":".encode() превращает текст в байты — хеш считается от байтов."},{"type":"code","q":"Хеш MD5","task":"Выведи MD5-хеш введённой строки.","starter":"import hashlib\ns = input()\n","tests":[{"stdin":"hello","out":"5d41402abc4b2a76b9719d911017c592"}],"hint":"<code>hashlib.md5(...)</code>","solution":"import hashlib\ns = input()\nprint(hashlib.md5(s.encode()).hexdigest())","explain":"MD5 короче — 32 символа."},{"type":"code","q":"Найди пароль по хешу (CTF)","task":"Тебе дали MD5-хеш (ввод). Проверь каждый пароль из словаря и выведи тот, чей хеш совпал. Если не нашёлся — <code>не найден</code>.","starter":"import hashlib\nwords = [\"123456\", \"qwerty\", \"dragon\", \"hello\", \"monkey\"]\nh = input()\n","tests":[{"stdin":"5d41402abc4b2a76b9719d911017c592","out":"hello"},{"stdin":"00000000000000000000000000000000","out":"не найден"}],"hint":"Цикл по words, сравни <code>hashlib.md5(w.encode()).hexdigest() == h</code>.","solution":"import hashlib\nwords = [\"123456\", \"qwerty\", \"dragon\", \"hello\", \"monkey\"]\nh = input()\nfound = \"не найден\"\nfor w in words:\n    if hashlib.md5(w.encode()).hexdigest() == h:\n        found = w\nprint(found)","explain":"Вот почему пароль из словаря без соли ломается мгновенно!"}]}]},{"id":"hack-u4","title":"Раздел 4. Шифры и криптография","lessons":[{"id":"hack-l9","title":"Шифр Цезаря","emoji":"🏛️","intro":"Юлий Цезарь сдвигал каждую букву на 3 позиции: A→D, B→E. Чтобы расшифровать — сдвигают обратно. Слабость: всего 26 вариантов сдвига, их легко перебрать. В Python: <code>ord(\"a\")</code> — номер буквы, <code>chr(97)</code> — буква по номеру.","questions":[{"type":"output","q":"Цезарь со сдвигом 1. Как зашифруется слово?","code":"cat","options":["dbu","bzs","cat","tac"],"explain":"c→d, a→b, t→u."},{"type":"output","q":"Что выведет код?","code":"print(ord(\"a\"))","options":["97","1","65","a"],"explain":"Номер «a» в таблице символов — 97, «A» — 65."},{"type":"output","q":"Что выведет код?","code":"print(chr(ord(\"a\") + 2))","options":["c","b","99","a2"],"explain":"97 + 2 = 99 → «c»."},{"type":"choice","q":"Как взломать шифр Цезаря, не зная сдвиг?","options":["Перебрать все 26 сдвигов и найти осмысленный текст","Никак","Нужен суперкомпьютер","Спросить Цезаря"],"explain":"Ключей мало — перебор занимает доли секунды."},{"type":"output","q":"Что выведет код? (% — остаток, чтобы z перешла в a)","code":"print((25 + 3) % 26)","options":["2","28","25","0"],"explain":"28 % 26 = 2 — после z снова идут a, b, c."},{"type":"input","q":"Функция, которая даёт букву по номеру","answers":["chr","chr()"],"explain":"chr — обратная к ord."}]},{"id":"hack-l10","title":"Кодирование ≠ шифрование","emoji":"🧩","intro":"<b>Base64</b> превращает любые данные в буквы и цифры — это <b>кодирование</b>, а не защита: раскодировать может любой без ключа. В CTF часто прячут флаг в Base64: строка с буквами, цифрами и знаками <code>=</code> на конце. <b>Шифрование</b> без ключа прочитать нельзя.","questions":[{"type":"choice","q":"Защищает ли Base64 секрет?","options":["Нет, это кодирование — раскодирует любой","Да, это надёжный шифр","Только длинные тексты","Да, если добавить ="],"explain":"Base64 — просто другой способ записи."},{"type":"choice","q":"Как часто выглядит Base64?","options":["ZmxhZ3t0ZXN0fQ==","#$%^&*","01010101","Привет"],"explain":"Латинские буквы, цифры, + и /, а на конце бывает = или ==."},{"type":"choice","q":"Чем шифрование отличается от кодирования?","options":["Для расшифровки нужен секретный ключ","Ничем","Шифрование быстрее","Кодирование секретнее"],"explain":"Без ключа зашифрованное не прочитать."},{"type":"output","q":"Что выведет код?","code":"import base64\nprint(base64.b64decode(\"aGk=\").decode())","options":["hi","aGk=","ошибку","b'hi'"],"explain":".decode() превращает байты обратно в текст."},{"type":"choice","q":"Какая функция кодирует в Base64?","options":["base64.b64encode","base64.hide","encrypt64","hashlib.b64"],"explain":"b64encode — закодировать, b64decode — раскодировать."},{"type":"input","q":"Модуль Python для Base64","answers":["base64"],"explain":"import base64"}]},{"id":"hack-l11","title":"Ключи и HTTPS","emoji":"🔐","intro":"<b>Симметричное</b> шифрование: один ключ шифрует и расшифровывает (AES). <b>Асимметричное</b>: пара ключей — открытый (всем) и закрытый (только у тебя), как RSA. На этом построен <b>HTTPS</b>: замочек в браузере значит, что данные между тобой и сайтом зашифрованы.","questions":[{"type":"choice","q":"Что значит замочек и https:// в адресе?","options":["Связь с сайтом зашифрована","Сайт точно не мошеннический","Сайт бесплатный","Сайт государственный"],"explain":"Важно: у фишингового сайта тоже может быть HTTPS! Замок — не гарантия честности."},{"type":"choice","q":"В асимметричном шифровании открытый ключ…","options":["можно давать всем — им только шифруют","надо прятать","это пароль от почты","не нужен"],"explain":"Расшифровать может только владелец закрытого ключа."},{"type":"choice","q":"Какой алгоритм — симметричный?","options":["AES","RSA","SHA-256","Base64"],"explain":"AES — один общий ключ. SHA-256 вообще хеш, а не шифр."},{"type":"choice","q":"Что опасно делать в открытом Wi-Fi кафе на сайтах без HTTPS?","options":["Вводить пароли — их могут перехватить","Читать новости","Смотреть погоду","Ничего не опасно"],"explain":"Без шифрования данные идут «открыткой»."},{"type":"output","q":"XOR: что выведет код?","code":"print(5 ^ 3)","options":["6","8","2","15"],"explain":"101 XOR 011 = 110 = 6. XOR — основа многих шифров."},{"type":"input","q":"Протокол защищённых сайтов (5 букв)","answers":["HTTPS","https"],"explain":"S — Secure."}]},{"id":"hack-p4","title":"Практика: шифровальщик","emoji":"💻","intro":"Пишем свои шифровалки на Python.","questions":[{"type":"code","q":"Шифр Цезаря","task":"Первая строка — слово из маленьких латинских букв, вторая — сдвиг. Выведи зашифрованное слово (после z идёт a).","starter":"word = input()\nk = int(input())\n","tests":[{"stdin":"cat\n1","out":"dbu"},{"stdin":"xyz\n3","out":"abc"},{"stdin":"hello\n13","out":"uryyb"}],"hint":"Для буквы c: <code>chr((ord(c) - 97 + k) % 26 + 97)</code>.","solution":"word = input()\nk = int(input())\nres = \"\"\nfor c in word:\n    res += chr((ord(c) - 97 + k) % 26 + 97)\nprint(res)","explain":"Сдвиг 13 называют ROT13 — его часто встречают в CTF."},{"type":"code","q":"Раскодируй Base64","task":"Программа получает строку Base64. Выведи раскодированный текст.","starter":"import base64\ns = input()\n","tests":[{"stdin":"ZmxhZ3tiYXNlNjR9","out":"flag{base64}"},{"stdin":"aGk=","out":"hi"}],"hint":"<code>base64.b64decode(s).decode()</code>","solution":"import base64\ns = input()\nprint(base64.b64decode(s).decode())","explain":"Классика CTF: флаг в Base64."},{"type":"code","q":"Взлом Цезаря перебором","task":"Программа получает слово, зашифрованное Цезарем с неизвестным сдвигом. Известно, что исходное слово начинается на <code>f</code>. Выведи исходное слово.","starter":"w = input()\n","tests":[{"stdin":"iodj","out":"flag"},{"stdin":"sbk","out":"fox"}],"hint":"Перебери k от 0 до 25, расшифруй сдвигом назад и проверь первую букву.","solution":"w = input()\nfor k in range(26):\n    s = \"\"\n    for c in w:\n        s += chr((ord(c) - 97 - k) % 26 + 97)\n    if s[0] == \"f\":\n        print(s)\n        break","explain":"Подсказка о первой букве — как в настоящих CTF: флаг начинается с flag."}]}]},{"id":"hack-u5","title":"Раздел 5. Как устроен интернет","lessons":[{"id":"hack-l12","title":"IP-адреса","emoji":"🌐","intro":"У каждого устройства в сети есть <b>IP-адрес</b>, например <code>192.168.1.10</code>: 4 числа от 0 до 255 через точку (это IPv4). Адреса <code>192.168.x.x</code> и <code>10.x.x.x</code> — домашние (локальные), <code>127.0.0.1</code> — «я сам» (localhost).","questions":[{"type":"choice","q":"Какой IP-адрес правильный?","options":["192.168.0.1","256.1.1.1","192.168.1","1.2.3.4.5"],"explain":"4 числа, каждое от 0 до 255."},{"type":"choice","q":"Что такое 127.0.0.1?","options":["Твой собственный компьютер (localhost)","Сервер Google","Адрес роутера всегда","Ошибка"],"explain":"Обращение «к себе»."},{"type":"choice","q":"Какой адрес — домашней (локальной) сети?","options":["192.168.1.5","8.8.8.8","1.1.1.1","77.88.8.8"],"explain":"192.168.x.x не виден из интернета напрямую."},{"type":"choice","q":"Сколько разных значений у одного числа в IPv4?","options":["256 (0–255)","100","1000","10"],"explain":"Одно число — это байт, 8 бит."},{"type":"choice","q":"Зачем появился IPv6?","options":["Адресов IPv4 (~4 млрд) не хватило на все устройства","Для красоты","IPv4 запретили","Он короче"],"explain":"IPv6 — 128 бит, адресов хватит на всё."},{"type":"input","q":"Как называют адрес 127.0.0.1 (одно слово)?","answers":["localhost"],"explain":"Local host — «этот компьютер»."}]},{"id":"hack-l13","title":"Порты и сервисы","emoji":"🚪","intro":"Если IP — адрес дома, то <b>порт</b> — номер квартиры. На одном сервере работает много программ, у каждой свой порт: <code>80</code> — сайт (HTTP), <code>443</code> — HTTPS, <code>22</code> — SSH (удалённый терминал), <code>3389</code> — удалённый рабочий стол Windows. Открытый лишний порт — возможная дыра.","questions":[{"type":"choice","q":"Какой порт у HTTPS?","options":["443","80","22","21"],"explain":"443 — защищённые сайты, 80 — обычные."},{"type":"choice","q":"Что работает на порту 22?","options":["SSH — удалённое управление сервером","Почта","Игры","Ничего"],"explain":"Поэтому порт 22 так часто пытаются перебирать."},{"type":"choice","q":"Что делает сканер портов (например, nmap)?","options":["Показывает, какие порты открыты на сервере","Ускоряет интернет","Удаляет вирусы","Взламывает пароли"],"explain":"Админы сканируют свои серверы, чтобы закрыть лишнее. Чужие сканировать без разрешения нельзя."},{"type":"choice","q":"Почему опасно оставлять открытыми ненужные порты?","options":["Каждый открытый сервис — возможная точка атаки","Компьютер греется","Это занимает место","Не опасно"],"explain":"Принцип: открыто только то, что нужно."},{"type":"choice","q":"Что такое файрвол (firewall)?","options":["Защита, которая пропускает или блокирует соединения","Антивирус","Пароль","Браузер"],"explain":"Межсетевой экран — «охранник на входе»."},{"type":"input","q":"Порт обычного HTTP","answers":["80"],"explain":"А HTTPS — 443."}]},{"id":"hack-l14","title":"DNS и пакеты","emoji":"📦","intro":"<b>DNS</b> — «телефонная книга» интернета: превращает имя <code>google.com</code> в IP-адрес. Данные по сети идут <b>пакетами</b> — маленькими кусочками. Программа <b>Wireshark</b> показывает пакеты — так ищут проблемы в своей сети.","questions":[{"type":"choice","q":"Что делает DNS?","options":["Находит IP-адрес по имени сайта","Шифрует пароли","Блокирует рекламу","Хранит фото"],"explain":"Без DNS пришлось бы запоминать цифры."},{"type":"choice","q":"Что такое DNS-спуфинг?","options":["Подмена ответа DNS, чтобы отправить на поддельный сайт","Быстрый DNS","Новый браузер","Сбой электричества"],"explain":"Пишешь правильный адрес — а попадаешь на фальшивый."},{"type":"choice","q":"Как данные передаются по сети?","options":["Маленькими пакетами","Одним огромным файлом","По телефону","Через флешку"],"explain":"Пакеты могут идти разными путями и собираются на месте."},{"type":"choice","q":"Для чего Wireshark?","options":["Смотреть сетевые пакеты и искать проблемы","Рисовать","Играть","Писать музыку"],"explain":"Главный инструмент сетевых инженеров. Применять — только в своей сети."},{"type":"choice","q":"Команда ping…","options":["проверяет, отвечает ли компьютер по сети","удаляет файлы","взламывает Wi-Fi","выключает компьютер"],"explain":"ping google.com — проверить связь."},{"type":"input","q":"Система, которая переводит имена сайтов в IP (3 буквы)","answers":["DNS","dns"],"explain":"Domain Name System."}]},{"id":"hack-p5","title":"Практика: сетевые утилиты","emoji":"💻","intro":"Разбираем сетевые адреса на Python.","questions":[{"type":"code","q":"Проверка IP","task":"Программа получает строку. Выведи <code>верный</code>, если это правильный IPv4-адрес (4 числа 0–255 через точку), иначе <code>неверный</code>.","starter":"ip = input()\n","tests":[{"stdin":"192.168.1.1","out":"верный"},{"stdin":"256.1.1.1","out":"неверный"},{"stdin":"10.0.0","out":"неверный"},{"stdin":"a.b.c.d","out":"неверный"}],"hint":"<code>ip.split(\".\")</code>, проверь, что частей 4, все <code>isdigit()</code> и от 0 до 255.","solution":"ip = input()\nparts = ip.split(\".\")\nok = len(parts) == 4 and all(p.isdigit() and 0 <= int(p) <= 255 for p in parts)\nprint(\"верный\" if ok else \"неверный\")","explain":"Проверка ввода — первая линия защиты любой программы."},{"type":"code","q":"Что на порту?","task":"Программа получает номер порта. Выведи сервис: 22 — <code>SSH</code>, 80 — <code>HTTP</code>, 443 — <code>HTTPS</code>, 3389 — <code>RDP</code>, иначе <code>неизвестно</code>.","starter":"port = int(input())\n","tests":[{"stdin":"443","out":"HTTPS"},{"stdin":"22","out":"SSH"},{"stdin":"1234","out":"неизвестно"}],"hint":"Словарь <code>{22: \"SSH\", ...}</code> и метод <code>.get(port, \"неизвестно\")</code>.","solution":"port = int(input())\nsvc = {22: \"SSH\", 80: \"HTTP\", 443: \"HTTPS\", 3389: \"RDP\"}\nprint(svc.get(port, \"неизвестно\"))","explain":"Так сканеры подписывают найденные порты."},{"type":"code","q":"Домашний адрес?","task":"Программа получает IP. Выведи <code>локальный</code>, если он начинается с <code>192.168.</code> или <code>10.</code>, либо равен <code>127.0.0.1</code>. Иначе — <code>внешний</code>.","starter":"ip = input()\n","tests":[{"stdin":"192.168.0.5","out":"локальный"},{"stdin":"10.1.2.3","out":"локальный"},{"stdin":"8.8.8.8","out":"внешний"},{"stdin":"127.0.0.1","out":"локальный"}],"hint":"<code>ip.startswith((\"192.168.\", \"10.\"))</code>","solution":"ip = input()\nif ip.startswith((\"192.168.\", \"10.\")) or ip == \"127.0.0.1\":\n    print(\"локальный\")\nelse:\n    print(\"внешний\")","explain":"startswith умеет принимать кортеж вариантов."}]}]},{"id":"hack-u6","title":"Раздел 6. Терминал Linux","lessons":[{"id":"hack-l15","title":"Первые команды","emoji":"🐧","intro":"Почти все серверы работают на <b>Linux</b>, а хакеры работают в <b>терминале</b>. Главные команды: <code>pwd</code> — где я, <code>ls</code> — что в папке, <code>cd папка</code> — перейти, <code>cat файл</code> — показать файл, <code>mkdir</code> — создать папку.","questions":[{"type":"choice","q":"Какая команда показывает файлы в папке?","options":["ls","cd","cat","pwd"],"explain":"ls — list."},{"type":"choice","q":"Как перейти в папку secret?","options":["cd secret","ls secret","go secret","open secret"],"explain":"cd — change directory."},{"type":"choice","q":"Что делает cat flag.txt?","options":["Показывает содержимое файла","Удаляет файл","Рисует кота","Создаёт файл"],"explain":"В CTF это первая команда, когда нашёл flag.txt."},{"type":"choice","q":"Как увидеть скрытые файлы (начинаются с точки)?","options":["ls -a","ls -hidden","cat .","show all"],"explain":"-a — all, включая скрытые .файлы."},{"type":"choice","q":"Что значит cd ..?","options":["Подняться в папку выше","Удалить папку","Перейти в корень","Ошибка"],"explain":".. — родительская папка."},{"type":"input","q":"Команда «где я сейчас?»","answers":["pwd"],"explain":"Print Working Directory."}]},{"id":"hack-l16","title":"Поиск: grep и find","emoji":"🔎","intro":"<code>grep слово файл</code> — найти строки со словом. <code>find / -name \"*.txt\"</code> — найти файлы по имени. Знак <code>|</code> (pipe) передаёт вывод одной команды в другую: <code>cat log.txt | grep error</code>.","questions":[{"type":"choice","q":"Как найти строки со словом flag в файле notes.txt?","options":["grep flag notes.txt","find flag","cat flag","ls flag"],"explain":"grep ищет внутри файлов."},{"type":"choice","q":"Что делает знак | ?","options":["Передаёт вывод одной команды на вход другой","Удаляет","Делит числа","Ставит пароль"],"explain":"Pipe — «труба» между командами."},{"type":"choice","q":"grep -i ищет…","options":["без учёта больших и маленьких букв","только цифры","в интернете","в картинках"],"explain":"-i — ignore case."},{"type":"choice","q":"Как найти все файлы .log?","options":["find / -name \"*.log\"","grep *.log","ls -log","cat *.log -find"],"explain":"find ищет файлы по имени, grep — текст в файлах."},{"type":"choice","q":"Что делает wc -l file?","options":["Считает строки в файле","Удаляет строки","Шифрует файл","Печатает файл"],"explain":"word count -lines."},{"type":"input","q":"Команда поиска текста внутри файлов","answers":["grep"],"explain":"grep — главный друг хакера и админа."}]},{"id":"hack-l17","title":"Права и sudo","emoji":"🛡️","intro":"У файла три группы прав: владелец, группа, остальные. Буквы: <code>r</code> — читать (4), <code>w</code> — писать (2), <code>x</code> — запускать (1). <code>rwxr-xr--</code> = 754. <code>chmod 700 файл</code> — только владельцу. <code>sudo</code> — выполнить от имени администратора (root).","questions":[{"type":"output","q":"Сколько это числом: rw- ?","code":"r=4, w=2, x=1","options":["6","7","5","3"],"explain":"4 + 2 = 6."},{"type":"choice","q":"Что значит chmod 777?","options":["Все могут читать, писать и запускать — опасно!","Только владелец","Никто","Файл скрыт"],"explain":"Права 777 на сервере — частая уязвимость."},{"type":"choice","q":"Кто такой root?","options":["Главный администратор Linux с полными правами","Вирус","Папка с играми","Обычный пользователь"],"explain":"Получить root — цель многих атак. Поэтому root-права дают только кому нужно."},{"type":"choice","q":"Что делает sudo?","options":["Запускает команду с правами администратора","Удаляет систему","Выключает","Показывает пароль"],"explain":"SuperUser DO."},{"type":"choice","q":"Принцип наименьших привилегий — это…","options":["Давать только те права, которые реально нужны","Давать всем root","Не давать прав никому","Менять пароль каждый день"],"explain":"Меньше прав — меньше вреда при взломе."},{"type":"input","q":"Права r-x числом","answers":["5"],"explain":"4 + 1 = 5."}]},{"id":"hack-p6","title":"Практика: права файлов","emoji":"💻","intro":"Разбираем права файлов Linux на Python.","questions":[{"type":"code","q":"rwx → число","task":"Программа получает три символа прав, например <code>rw-</code>. Выведи число (r=4, w=2, x=1).","starter":"p = input()\n","tests":[{"stdin":"rwx","out":"7"},{"stdin":"rw-","out":"6"},{"stdin":"r--","out":"4"},{"stdin":"---","out":"0"}],"hint":"Сложи: если p[0]==\"r\" +4, p[1]==\"w\" +2, p[2]==\"x\" +1.","solution":"p = input()\nn = 0\nif p[0] == \"r\":\n    n += 4\nif p[1] == \"w\":\n    n += 2\nif p[2] == \"x\":\n    n += 1\nprint(n)","explain":"Так и считается chmod."},{"type":"code","q":"Полные права","task":"Программа получает 9 символов прав, например <code>rwxr-xr--</code>. Выведи три цифры, например <code>754</code>.","starter":"s = input()\n","tests":[{"stdin":"rwxr-xr--","out":"754"},{"stdin":"rw-r--r--","out":"644"},{"stdin":"rwxrwxrwx","out":"777"}],"hint":"Разбей на куски по 3: <code>s[0:3]</code>, <code>s[3:6]</code>, <code>s[6:9]</code>.","solution":"s = input()\nres = \"\"\nfor i in range(0, 9, 3):\n    p = s[i:i+3]\n    n = (4 if p[0] == \"r\" else 0) + (2 if p[1] == \"w\" else 0) + (1 if p[2] == \"x\" else 0)\n    res += str(n)\nprint(res)","explain":"644 — обычный файл, 755 — программа, 777 — тревога!"},{"type":"code","q":"Опасные права","task":"Программа получает права числом (например <code>777</code>). Если последняя цифра (права «остальных») содержит запись — это 2, 3, 6 или 7 — выведи <code>опасно</code>, иначе <code>ок</code>.","starter":"m = input()\n","tests":[{"stdin":"777","out":"опасно"},{"stdin":"644","out":"ок"},{"stdin":"702","out":"опасно"}],"hint":"<code>m[-1] in \"2367\"</code>","solution":"m = input()\nprint(\"опасно\" if m[-1] in \"2367\" else \"ок\")","explain":"Запись для всех — любой пользователь может подменить файл."}]}]},{"id":"hack-u7","title":"Раздел 7. Уязвимости сайтов и защита","lessons":[{"id":"hack-l18","title":"Как работает сайт","emoji":"🕸️","intro":"Браузер отправляет серверу <b>HTTP-запрос</b>: <code>GET</code> — получить страницу, <code>POST</code> — отправить данные (форму). Сервер отвечает кодом: <code>200</code> — ок, <code>404</code> — не найдено, <code>403</code> — запрещено, <code>500</code> — ошибка сервера. <b>Cookie</b> — маленькие данные, по которым сайт тебя помнит.","questions":[{"type":"choice","q":"Какой метод отправляет форму с паролем?","options":["POST","GET","PING","PUT ME"],"explain":"GET кладёт данные в адрес — для паролей не годится."},{"type":"choice","q":"Что значит ответ 404?","options":["Страница не найдена","Всё хорошо","Нет доступа","Сервер сломался"],"explain":"404 Not Found."},{"type":"choice","q":"Что значит 403?","options":["Доступ запрещён","Страница найдена","Перегрузка","Пароль верный"],"explain":"403 Forbidden."},{"type":"choice","q":"Зачем сайту cookie сессии?","options":["Помнить, что ты уже вошёл","Чтобы показать рекламу печенья","Чтобы ускорить интернет","Ни зачем"],"explain":"Кто украл cookie сессии — тот входит без пароля. Поэтому их берегут."},{"type":"choice","q":"Главное правило веб-безопасности?","options":["Никогда не доверять данным от пользователя","Доверять всем","Писать код без проверок","Прятать кнопки"],"explain":"Любой ввод может быть атакой — его проверяют и экранируют."},{"type":"input","q":"Код ответа «всё хорошо»","answers":["200"],"explain":"200 OK."}]},{"id":"hack-l19","title":"SQL-инъекция","emoji":"💉","intro":"Если программист склеивает запрос из ввода: <code>\"SELECT * FROM users WHERE name='\" + name + \"'\"</code>, хитрый ввод с кавычкой меняет смысл запроса. Это <b>SQL-инъекция</b> — одна из самых известных уязвимостей. Защита: <b>параметризованные запросы</b> — данные передаются отдельно от команды и никогда не становятся кодом.","questions":[{"type":"choice","q":"Из-за чего возникает SQL-инъекция?","options":["Ввод пользователя склеивают с текстом запроса","Из-за медленного сервера","Из-за длинного пароля","Из-за HTTPS"],"explain":"Данные смешались с кодом."},{"type":"choice","q":"Как правильно защититься?","options":["Параметризованные запросы (плейсхолдеры ?)","Убрать поле ввода","Сделать сайт зелёным","Запретить букву а"],"explain":"cursor.execute(\"... WHERE name = ?\", (name,)) — данные отдельно."},{"type":"bug","q":"Где опасность?","code":"q = \"SELECT * FROM users WHERE id = \" + user_input\ncursor.execute(q)","options":["Ввод вклеен прямо в запрос","Нет ошибки","Нужно SELECT писать маленькими","Нет точки с запятой"],"explain":"Надо: cursor.execute(\"SELECT * FROM users WHERE id = ?\", (user_input,))."},{"type":"choice","q":"Какой символ чаще всего «ломает» склеенный SQL-запрос?","options":["Одинарная кавычка '","Буква z","Пробел","Цифра 7"],"explain":"Кавычка закрывает строку раньше времени — поэтому её нельзя доверять."},{"type":"choice","q":"Что ещё уменьшает вред от инъекции?","options":["Давать программе в базе только нужные права","Хранить пароли открыто","Отключить логи","Один пароль на всё"],"explain":"Снова принцип наименьших привилегий."},{"type":"input","q":"Как называют запросы с данными отдельно от команды? Параметри___ запросы","answers":["зованные","параметризованные"],"explain":"Prepared statements."}]},{"id":"hack-l20","title":"XSS","emoji":"🧨","intro":"<b>XSS</b> (межсайтовый скриптинг): если сайт выводит чужой комментарий как HTML, туда можно вставить <code>&lt;script&gt;</code>, и он выполнится у всех читателей. Защита — <b>экранирование</b>: заменять <code>&lt;</code> на <code>&amp;lt;</code>, <code>&gt;</code> на <code>&amp;gt;</code>, <code>&amp;</code> на <code>&amp;amp;</code>, кавычки — тоже. Тогда код показывается как текст.","questions":[{"type":"choice","q":"Что такое XSS?","options":["Внедрение чужого скрипта на страницу через ввод","Размер одежды","Вид пароля","Быстрый Wi-Fi"],"explain":"Cross-Site Scripting."},{"type":"choice","q":"Чем опасен XSS?","options":["Скрипт может украсть cookie и войти от имени жертвы","Ничем","Страница станет красивее","Сломается клавиатура"],"explain":"Поэтому важные cookie помечают HttpOnly — скрипты их не видят."},{"type":"choice","q":"Как защититься от XSS?","options":["Экранировать спецсимволы при выводе","Запретить комментарии навсегда","Писать сайт на Python","Ставить капчу"],"explain":"Экранированный <script> — просто текст."},{"type":"output","q":"Что станет с текстом после экранирования?","code":"<b>","options":["&lt;b&gt;","<b>","b","Пусто"],"explain":"< → &lt;, > → &gt;."},{"type":"choice","q":"Какая функция Python экранирует HTML?","options":["html.escape","print","str.upper","hashlib.md5"],"explain":"import html; html.escape(text)."},{"type":"input","q":"Атака через вставку скрипта (3 буквы)","answers":["XSS","xss"],"explain":"Cross-Site Scripting."}]},{"id":"hack-p7","title":"Практика: защищаем сайт","emoji":"💻","intro":"Пишем защиту для сайта на Python.","questions":[{"type":"code","q":"Своё экранирование","task":"Программа получает строку. Замени <code>&amp;</code> на <code>&amp;amp;</code>, <code>&lt;</code> на <code>&amp;lt;</code>, <code>&gt;</code> на <code>&amp;gt;</code> и выведи результат. Важно: <code>&amp;</code> заменяют первым!","starter":"s = input()\n","tests":[{"stdin":"<script>alert(1)</script>","out":"&lt;script&gt;alert(1)&lt;/script&gt;"},{"stdin":"a & b","out":"a &amp; b"},{"stdin":"привет","out":"привет"}],"hint":"<code>s.replace(\"&\", \"&amp;\")</code>, затем остальные.","solution":"s = input()\ns = s.replace(\"&\", \"&amp;\").replace(\"<\", \"&lt;\").replace(\">\", \"&gt;\")\nprint(s)","explain":"Если сначала заменить < на &lt;, а потом & — получится &amp;lt;. Порядок важен!"},{"type":"code","q":"Подозрительный ввод","task":"Программа получает строку. Выведи <code>подозрительно</code>, если в ней есть одинарная кавычка, <code>&lt;script</code> (в любом регистре) или <code>--</code>. Иначе — <code>чисто</code>.","starter":"s = input()\n","tests":[{"stdin":"admin' --","out":"подозрительно"},{"stdin":"<SCRIPT>x","out":"подозрительно"},{"stdin":"Ярослав","out":"чисто"}],"hint":"<code>s.lower()</code> и оператор <code>in</code>.","solution":"s = input()\nlow = s.lower()\nif \"'\" in s or \"<script\" in low or \"--\" in s:\n    print(\"подозрительно\")\nelse:\n    print(\"чисто\")","explain":"Так работают простые сигнатуры WAF. Но главная защита — параметры и экранирование, а не поиск «плохих» слов."},{"type":"code","q":"Безопасный запрос","task":"Выведи ровно строку безопасного SQL-запроса с плейсхолдером: <code>SELECT * FROM users WHERE name = ?</code>","starter":"# выведи безопасный запрос\n","tests":[{"out":"SELECT * FROM users WHERE name = ?"}],"hint":"Просто print нужной строки.","solution":"print(\"SELECT * FROM users WHERE name = ?\")","explain":"Знак ? — место для данных, которые подставит сама база, без склейки."}]}]},{"id":"hack-u8","title":"Раздел 8. Фишинг и социальная инженерия","lessons":[{"id":"hack-l21","title":"Взлом человека","emoji":"🎭","intro":"<b>Социальная инженерия</b> — когда обманывают не компьютер, а человека: притворяются поддержкой, другом, учителем. Давят на срочность («аккаунт заблокируют через 10 минут!»), жадность («выиграл скины!») или страх. Это самый частый способ взлома.","questions":[{"type":"choice","q":"Тебе пишут: «Я модератор игры, скинь пароль, проверим аккаунт». Это…","options":["Мошенник — настоящие модераторы пароли не просят","Модератор","Друг","Бот поддержки"],"explain":"Пароль не спрашивает никто и никогда."},{"type":"choice","q":"Какой приём используют мошенники?","options":["Срочность и давление","Долгие объяснения","Честность","Вежливый отказ"],"explain":"Срочность мешает подумать."},{"type":"choice","q":"«Друг» пишет с нового аккаунта и просит денег. Что делать?","options":["Проверить, позвонив другу по старому номеру","Сразу отправить","Отправить половину","Отправить пароль"],"explain":"Аккаунты друзей тоже взламывают."},{"type":"choice","q":"Что такое «претекстинг»?","options":["Обман с выдуманной историей-предлогом","Текст перед уроком","Вид вируса","Шифр"],"explain":"«Я из банка, у вас подозрительная операция…» — классический претекст."},{"type":"choice","q":"Нашёл на улице флешку «Оценки 9Б». Что делать?","options":["Не вставлять в компьютер — может быть вирус","Открыть дома","Открыть в школе","Отдать другу"],"explain":"Подброшенные флешки — реальная атака."},{"type":"input","q":"Самое уязвимое звено в безопасности — это ___","answers":["человек","люди"],"explain":"Поэтому обучение людей важнее любой программы."}]},{"id":"hack-l22","title":"Фишинговые ссылки","emoji":"🎣","intro":"<b>Фишинг</b> — поддельный сайт, похожий на настоящий, чтобы ты ввёл пароль. Признаки: странный домен (<code>vk-login.ru</code>, <code>rob1ox.com</code>), ошибки, «срочно». Главное — смотреть на <b>домен</b>: в адресе <code>https://vk.com.security-check.ru/</code> настоящий домен — <code>security-check.ru</code>, а не vk.com!","questions":[{"type":"choice","q":"Какая ссылка настоящая?","options":["https://www.roblox.com/","https://rob1ox.com/","https://roblox.com.free-robux.ru/","https://roblox-gift.net/"],"explain":"Только roblox.com в конце домена."},{"type":"choice","q":"Какой настоящий домен у адреса https://vk.com.login-check.ru/page ?","options":["login-check.ru","vk.com","page","https"],"explain":"Домен читается справа налево до первого «/». Это сайт login-check.ru."},{"type":"choice","q":"Тебе пришло «Бесплатные робуксы — введи логин и пароль». Это…","options":["Фишинг","Подарок","Акция Roblox","Ошибка"],"explain":"Бесплатные робуксы/скины за пароль — всегда обман."},{"type":"choice","q":"Что сделать, если уже ввёл пароль на фишинговом сайте?","options":["Сразу сменить пароль и включить 2FA, рассказать взрослым","Ничего","Ввести ещё раз","Удалить браузер"],"explain":"Чем быстрее — тем лучше."},{"type":"choice","q":"Что такое тайпсквоттинг?","options":["Домены с опечатками: gooogle.com, yandeks.ru","Быстрая печать","Скорость Wi-Fi","Вид шифра"],"explain":"Расчёт на то, что ты опечатаешься или не заметишь."},{"type":"input","q":"Как называется обман через поддельные сайты и письма?","answers":["фишинг","phishing"],"explain":"От fishing — рыбалка: «ловят» пароли."}]},{"id":"hack-p8","title":"Практика: детектор фишинга","emoji":"💻","intro":"Пишем детектор фишинговых ссылок.","questions":[{"type":"code","q":"Достань домен","task":"Программа получает ссылку вида <code>https://домен/путь</code>. Выведи только домен.","starter":"url = input()\n","tests":[{"stdin":"https://vk.com/feed","out":"vk.com"},{"stdin":"https://vk.com.login-check.ru/page","out":"vk.com.login-check.ru"},{"stdin":"http://example.org/","out":"example.org"}],"hint":"Убери всё до <code>//</code>: <code>url.split(\"//\")[1]</code>, потом возьми часть до первого <code>/</code>.","solution":"url = input()\nhost = url.split(\"//\")[1].split(\"/\")[0]\nprint(host)","explain":"Первый шаг любой проверки ссылки."},{"type":"code","q":"Настоящий ли это сайт?","task":"Первая строка — домен из ссылки, вторая — настоящий домен (например <code>roblox.com</code>). Выведи <code>настоящий</code>, если домен равен настоящему или кончается на <code>.</code> + настоящий (поддомен). Иначе — <code>фишинг</code>.","starter":"host = input()\nreal = input()\n","tests":[{"stdin":"www.roblox.com\nroblox.com","out":"настоящий"},{"stdin":"roblox.com.free.ru\nroblox.com","out":"фишинг"},{"stdin":"fakeroblox.com\nroblox.com","out":"фишинг"},{"stdin":"roblox.com\nroblox.com","out":"настоящий"}],"hint":"Важно проверять <code>endswith(\".\" + real)</code>, а не просто <code>endswith(real)</code> — иначе fakeroblox.com пройдёт!","solution":"host = input()\nreal = input()\nif host == real or host.endswith(\".\" + real):\n    print(\"настоящий\")\nelse:\n    print(\"фишинг\")","explain":"Ошибка «endswith без точки» встречалась даже в настоящих программах."},{"type":"code","q":"Подозрительные слова","task":"Программа получает текст сообщения. Посчитай, сколько из слов <code>срочно</code>, <code>пароль</code>, <code>бесплатно</code>, <code>заблокирован</code> в нём встречается (регистр не важен). Если 2 и больше — выведи <code>похоже на мошенников</code>, иначе <code>вроде нормально</code>.","starter":"text = input().lower()\nwords = [\"срочно\", \"пароль\", \"бесплатно\", \"заблокирован\"]\n","tests":[{"stdin":"СРОЧНО! Аккаунт заблокирован, пришли пароль","out":"похоже на мошенников"},{"stdin":"Привет, пойдём гулять?","out":"вроде нормально"}],"hint":"<code>sum(1 for w in words if w in text)</code>","solution":"text = input().lower()\nwords = [\"срочно\", \"пароль\", \"бесплатно\", \"заблокирован\"]\ncount = sum(1 for w in words if w in text)\nprint(\"похоже на мошенников\" if count >= 2 else \"вроде нормально\")","explain":"Похоже работают простые спам-фильтры."}]}]},{"id":"hack-u9","title":"Раздел 9. Защита, вирусы и логи","lessons":[{"id":"hack-l23","title":"Вредоносные программы","emoji":"🦠","intro":"<b>Вирус</b> заражает другие файлы, <b>троян</b> притворяется полезной программой (чит, «бесплатная игра»), <b>шифровальщик</b> шифрует файлы и требует выкуп, <b>стилер</b> ворует пароли и cookie. Защита: скачивать только с официальных сайтов, обновляться, антивирус, резервные копии.","questions":[{"type":"choice","q":"Скачал «чит для Roblox» с непонятного сайта. Что это может быть?","options":["Троян или стилер паролей","Точно чит","Обновление Windows","Ничего страшного"],"explain":"Читы — любимая маскировка стилеров."},{"type":"choice","q":"Что делает шифровальщик?","options":["Шифрует файлы и требует выкуп","Ускоряет компьютер","Чистит мусор","Обновляет игры"],"explain":"Лучшая защита — резервные копии."},{"type":"choice","q":"Зачем ставить обновления?","options":["Они закрывают найденные уязвимости","Чтобы сменить обои","Незачем","Чтобы замедлить компьютер"],"explain":"Многие атаки работают только на старых версиях."},{"type":"choice","q":"Что такое бэкап?","options":["Резервная копия важных файлов","Рюкзак","Вирус","Пароль"],"explain":"Правило 3-2-1: 3 копии, 2 разных носителя, 1 — в другом месте."},{"type":"choice","q":"Что ворует стилер?","options":["Сохранённые пароли, cookie, аккаунты","Электричество","Клавиатуру","Интернет"],"explain":"Поэтому опасно хранить пароли в браузере на заражённом ПК."},{"type":"input","q":"Программа, которая притворяется полезной (как конь из Трои)","answers":["троян","trojan"],"explain":"Троянский конь."}]},{"id":"hack-l24","title":"Логи и обнаружение атак","emoji":"📜","intro":"Серверы записывают все события в <b>логи</b>: кто вошёл, откуда, ошибся ли паролем. Специалисты по защите (<b>blue team</b>) читают логи и замечают атаки: например, 50 неудачных входов с одного IP за минуту — это перебор. Тогда IP блокируют.","questions":[{"type":"choice","q":"Что такое лог?","options":["Журнал событий программы или сервера","Бревно","Пароль","Вирус"],"explain":"Логи — главная улика при расследовании."},{"type":"choice","q":"Что значит много неудачных входов с одного IP подряд?","options":["Скорее всего перебор пароля","Пользователь просто устал","Сервер сломан","Всё нормально"],"explain":"Такой IP блокируют, например программой fail2ban."},{"type":"choice","q":"Red team и blue team — это…","options":["Атакующие (по договору) и защитники","Футбольные команды","Цвета сайта","Вирусы"],"explain":"Red — изображают хакеров, Blue — защищают."},{"type":"choice","q":"Почему злоумышленники стирают логи?","options":["Чтобы скрыть следы","Чтобы освободить место","Случайно","Так требует закон"],"explain":"Поэтому логи копируют на отдельный сервер."},{"type":"choice","q":"Что такое SIEM?","options":["Система, которая собирает логи и ищет атаки","Шифр","Браузер","Видеокарта"],"explain":"Центр мониторинга безопасности работает с SIEM."},{"type":"input","q":"Команда защитников называется ___ team","answers":["blue","синяя"],"explain":"Blue team."}]},{"id":"hack-p9","title":"Практика: охота в логах","emoji":"💻","intro":"Ищем атаки в логах, как настоящий специалист по защите.","questions":[{"type":"code","q":"Посчитай неудачи","task":"Первая строка — число записей n, дальше n строк вида <code>IP OK</code> или <code>IP FAIL</code>. Выведи количество FAIL.","starter":"n = int(input())\n","tests":[{"stdin":"4\n1.1.1.1 FAIL\n2.2.2.2 OK\n1.1.1.1 FAIL\n3.3.3.3 FAIL","out":"3"},{"stdin":"1\n5.5.5.5 OK","out":"0"}],"hint":"Цикл <code>for _ in range(n)</code>, <code>line.split()</code>.","solution":"n = int(input())\nfails = 0\nfor _ in range(n):\n    ip, status = input().split()\n    if status == \"FAIL\":\n        fails += 1\nprint(fails)","explain":"Первый шаг анализа."},{"type":"code","q":"Найди атакующего","task":"Тот же формат. Выведи IP-адреса, у которых 3 и больше FAIL, в порядке первого появления, каждый с новой строки. Если таких нет — <code>атак нет</code>.","starter":"n = int(input())\n","tests":[{"stdin":"6\n1.1.1.1 FAIL\n2.2.2.2 FAIL\n1.1.1.1 FAIL\n2.2.2.2 OK\n1.1.1.1 FAIL\n9.9.9.9 OK","out":"1.1.1.1"},{"stdin":"2\n1.1.1.1 FAIL\n2.2.2.2 FAIL","out":"атак нет"}],"hint":"Словарь <code>count[ip] = count.get(ip, 0) + 1</code>. Словари в Python помнят порядок добавления.","solution":"n = int(input())\ncount = {}\nfor _ in range(n):\n    ip, status = input().split()\n    if status == \"FAIL\":\n        count[ip] = count.get(ip, 0) + 1\nbad = [ip for ip in count if count[ip] >= 3]\nif bad:\n    for ip in bad:\n        print(ip)\nelse:\n    print(\"атак нет\")","explain":"Так и работает fail2ban: считает ошибки и блокирует."},{"type":"code","q":"Нужна ли резервная копия?","task":"Программа получает число дней с последнего бэкапа. Если больше 7 — выведи <code>срочно сделай бэкап</code>, иначе <code>всё в порядке</code>.","starter":"days = int(input())\n","tests":[{"stdin":"10","out":"срочно сделай бэкап"},{"stdin":"3","out":"всё в порядке"},{"stdin":"7","out":"всё в порядке"}],"hint":"if days > 7","solution":"days = int(input())\nprint(\"срочно сделай бэкап\" if days > 7 else \"всё в порядке\")","explain":"Автоматические напоминания — часть защиты."}]}]},{"id":"hack-u10","title":"Раздел 10. Финальный CTF","lessons":[{"id":"hack-l25","title":"Форензика и стеганография","emoji":"🔬","intro":"<b>Форензика</b> — расследование: что произошло на компьютере. <b>Метаданные</b> фото (EXIF) могут хранить место съёмки и модель телефона. <b>Стеганография</b> — прятать сообщение внутри картинки или текста, например в первых буквах строк.","questions":[{"type":"choice","q":"Что могут рассказать метаданные фото?","options":["Где и когда снято, каким телефоном","Ничего","Пароль от телефона","Имя кота"],"explain":"Поэтому перед публикацией фото метаданные лучше удалять."},{"type":"choice","q":"Что такое стеганография?","options":["Спрятать сообщение внутри другого файла или текста","Рисование","Вид пароля","Удаление файлов"],"explain":"Секрет не зашифрован, а спрятан."},{"type":"output","q":"Какое слово спрятано в первых буквах строк?","code":"Феи\nЛетают\nАж\nГоризонт","options":["ФЛАГ","ФЕЯ","ЛЕТО","АГОР"],"explain":"Акростих — простейшая стеганография."},{"type":"choice","q":"Команда strings в Linux…","options":["Показывает читаемый текст внутри любого файла","Удаляет строки","Шифрует","Играет музыку"],"explain":"В CTF флаг часто находится через strings файл | grep flag."},{"type":"choice","q":"Удалённый файл с флешки…","options":["Часто можно восстановить специальными программами","Исчезает навсегда сразу","Переходит в облако","Отправляется в полицию"],"explain":"Удаление обычно лишь помечает место свободным."},{"type":"input","q":"Метаданные фотографий называются (4 буквы)","answers":["EXIF","exif"],"explain":"Exchangeable Image File Format."}]},{"id":"hack-l26","title":"Путь хакера","emoji":"🚀","intro":"Что дальше? Учи Python, Linux и сети глубже. Тренируйся на легальных площадках: учебные CTF для школьников, учебные лаборатории. Есть олимпиады по информационной безопасности. Профессии: пентестер, аналитик SOC, исследователь уязвимостей, bug hunter.","questions":[{"type":"choice","q":"Где законно тренироваться дальше?","options":["Учебные CTF и тренировочные лаборатории","Сайт школы","Аккаунты друзей","Банковские сайты"],"explain":"Там всё специально сделано для взлома."},{"type":"choice","q":"Кто такой аналитик SOC?","options":["Защитник, который следит за атаками в реальном времени","Продавец носков","Игрок","Модератор чата"],"explain":"SOC — Security Operations Center."},{"type":"choice","q":"Что важнее всего для хакера?","options":["Понимать, как всё устроено, и действовать честно","Знать одну волшебную программу","Иметь чёрный капюшон","Печатать без ошибок"],"explain":"Знания + этика = профессия."},{"type":"choice","q":"Ты нашёл дыру в любимой игре. Твои действия?","options":["Сообщить разработчикам (часто за это дают награду)","Продать в Discord","Использовать для доната","Рассказать всем, как ломать"],"explain":"Ответственное раскрытие — путь белой шляпы."},{"type":"choice","q":"Какой язык чаще всего используют хакеры для своих инструментов?","options":["Python","HTML","Scratch","Excel"],"explain":"Ты уже пишешь на нём!"},{"type":"input","q":"Хороший хакер носит ___ шляпу","answers":["белую","white"],"explain":"Ты — белая шляпа!"}]},{"id":"hack-p10","title":"Финальный CTF","emoji":"🏆","intro":"Финальный CTF! Каждое задание прячет флаг.","questions":[{"type":"code","q":"Флаг в тексте","task":"Программа получает длинную строку. Где-то в ней спрятан флаг вида <code>flag{...}</code>. Выведи его целиком.","starter":"s = input()\n","tests":[{"stdin":"мусор123 flag{f0und_m3} ещё мусор","out":"flag{f0und_m3}"},{"stdin":"xxflag{a}yy","out":"flag{a}"}],"hint":"<code>start = s.find(\"flag{\")</code>, <code>end = s.find(\"}\", start)</code>.","solution":"s = input()\nstart = s.find(\"flag{\")\nend = s.find(\"}\", start)\nprint(s[start:end + 1])","explain":"Можно и регулярным выражением: re.search(r\"flag\\{.*?\\}\", s)."},{"type":"code","q":"Акростих","task":"Первая строка — число строк n, дальше n строк текста. Выведи слово из первых букв строк заглавными буквами.","starter":"n = int(input())\n","tests":[{"stdin":"4\nфеи\nлетают\nаж\nгоризонт","out":"ФЛАГ"},{"stdin":"2\nхорошо\nакула","out":"ХА"}],"hint":"Собирай <code>line[0]</code>, в конце <code>.upper()</code>.","solution":"n = int(input())\nw = \"\"\nfor _ in range(n):\n    w += input()[0]\nprint(w.upper())","explain":"Стеганография раскрыта!"},{"type":"code","q":"Двойная защита","task":"Флаг сначала зашифровали ROT13 (Цезарь со сдвигом 13, только маленькие латинские буквы; остальные символы не меняются), а потом закодировали в Base64. Получи строку Base64 и выведи исходный флаг.","starter":"import base64\ns = input()\n","tests":[{"stdin":"c3ludHt1bnB4cmV9","out":"flag{hacker}"}],"hint":"Сначала <code>base64.b64decode(s).decode()</code>, потом для каждой буквы a–z сдвиг на 13 (ROT13 сам себе обратный).","solution":"import base64\ns = input()\nt = base64.b64decode(s).decode()\nres = \"\"\nfor c in t:\n    if \"a\" <= c <= \"z\":\n        res += chr((ord(c) - 97 + 13) % 26 + 97)\n    else:\n        res += c\nprint(res)","explain":"Ты прошёл финальный CTF. Поздравляем, этичный хакер! 🕵️"}]}]}]}.units;
  const LESSONS = UNITS.flatMap(u => u.lessons.map(l => ({ ...l, unit: u.id })));
  const lessonById = id => LESSONS.find(l => l.id === id) || null;
  const lessonIndex = id => LESSONS.findIndex(l => l.id === id);
  const api = { lang: 'hack', UNITS, LESSONS, lessonById, lessonIndex };
  if (typeof module !== 'undefined' && module.exports) module.exports = api; else { root.COURSES = root.COURSES || {}; root.COURSES['hack'] = api; }
})(typeof self !== 'undefined' ? self : this);
